ESetup.exe ~335MB)","tree":{"sha":"cd9f8c5ed8a4eb9686d3c6639696b05414544a1f","url":"https://api.github.com/repos/Juliano-Soder/Micro-Front-End-Manager/git/trees/cd9f8c5ed8a4eb9686d3c6639696b05414544a1f"},"url":"https://api.github.com/repos/Juliano-Soder/Micro-Front-End-Manager/git/commits/121d5df975c1e6674e4b489a7800fbcf5c20fe26","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/108891114?v=4","events_url":"https://api.github.com/users/Juliano-Soder/events{/privacy}","followers_url":"https://api.github.com/users/Juliano-Soder/followers","following_url":"https://api.github.com/users/Juliano-Soder/following{/other_user}","gists_url":"https://api.github.com/users/Juliano-Soder/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Juliano-Soder","id":108891114,"login":"Juliano-Soder","node_id":"U_kgDOBn2L6g","organizations_url":"https://api.github.com/users/Juliano-Soder/orgs","received_events_url":"https://api.github.com/users/Juliano-Soder/received_events","repos_url":"https://api.github.com/users/Juliano-Soder/repos","site_admin":false,"starred_url":"https://api.github.com/users/Juliano-Soder/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Juliano-Soder/subscriptions","type":"User","url":"https://api.github.com/users/Juliano-Soder","user_view_type":"public"},"html_url":"https://github.com/Juliano-Soder/Micro-Front-End-Manager/commit/121d5df975c1e6674e4b489a7800fbcf5c20fe26","node_id":"C_kwDOOonvB9oAKDEyMWQ1ZGY5NzVjMWU2Njc0ZTRiNDg5YTc4MDBmYmNmNWMyMGZlMjY","parents":[{"html_url":"https://github.com/Juliano-Soder/Micro-Front-End-Manager/commit/d893fd486f12caa69e7e53a5f29ad0f9ada87c34","sha":"d893fd486f12caa69e7e53a5f29ad0f9ada87c34","url":"https://api.github.com/repos/Juliano-Soder/Micro-Front-End-Manager/commits/d893fd486f12caa69e7e53a5f29ad0f9ada87c34"}],"sha":"121d5df975c1e6674e4b489a7800fbcf5c20fe26","url":"h