nDeleted obsolete and insecure files: config.ts, config.d.ts, DebugPage.tsx, NetlifyBrain.ts.\nImproved overall frontend security posture and code organization.","tree":{"sha":"37c715a6cf4a3ddc7d5b18236e609134c676e34d","url":"https://api.github.com/repos/binder-git/seth-haus/git/trees/37c715a6cf4a3ddc7d5b18236e609134c676e34d"},"url":"https://api.github.com/repos/binder-git/seth-haus/git/commits/2556a734adaa01d0eeb82f19172461b6a11cd6a4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/957682?v=4","events_url":"https://api.github.com/users/binder-git/events{/privacy}","followers_url":"https://api.github.com/users/binder-git/followers","following_url":"https://api.github.com/users/binder-git/following{/other_user}","gists_url":"https://api.github.com/users/binder-git/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/binder-git","id":957682,"login":"binder-git","node_id":"MDQ6VXNlcjk1NzY4Mg==","organizations_url":"https://api.github.com/users/binder-git/orgs","received_events_url":"https://api.github.com/users/binder-git/received_events","repos_url":"https://api.github.com/users/binder-git/repos","site_admin":false,"starred_url":"https://api.github.com/users/binder-git/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/binder-git/subscriptions","type":"User","url":"https://api.github.com/users/binder-git","user_view_type":"public"},"html_url":"https://github.com/binder-git/seth-haus/commit/2556a734adaa01d0eeb82f19172461b6a11cd6a4","node_id":"C_kwDOOpaKl9oAKDI1NTZhNzM0YWRhYTAxZDBlZWI4MmYxOTE3MjQ2MWI2YTExY2Q2YTQ","parents":[{"html_url":"https://github.com/binder-git/seth-haus/commit/6f1a97e48bcc86ecb6d9fd13db4865ac0ae47203","sha":"6f1a97e48bcc86ecb6d9fd13db4865ac0ae47203","url":"https://api.github.com/repos/binder-git/seth-haus/commits/6f1a97e48bcc86ecb6d9fd13db4865ac0ae47203"}],"sha":"2556a734adaa01d0eeb82f19172